using System.Collections;
using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;

string assemblyPath = args[0];
AssemblyDependencyResolver resolver = new(assemblyPath);
AssemblyLoadContext.Default.Resolving += (_, name) =>
{
    string? path = resolver.ResolveAssemblyToPath(name);
    path ??= Path.Combine(Path.GetDirectoryName(assemblyPath)!, name.Name + ".dll");
    return File.Exists(path) ? AssemblyLoadContext.Default.LoadFromAssemblyPath(path) : null;
};
Assembly tests = AssemblyLoadContext.Default.LoadFromAssemblyPath(assemblyPath);
Type type = tests.GetType("Hexalith.Tenants.UI.Tests.Services.Gateways.TenantCommandGatewayTests", true)!;
object instance = Activator.CreateInstance(type)!;
IEnumerable cases = (IEnumerable)type.GetMethod("AmbiguousGrantExceptions")!.Invoke(null, null)!;
List<Exception> failures = [];
foreach (object[] row in cases)
{
    Exception exception = (Exception)row[0];
    if (exception is TimeoutException || exception.GetType() == typeof(OperationCanceledException)
        || exception.GetType().GetProperty("Retryable")?.GetValue(exception) is true)
    {
        failures.Add(exception);
    }
}
string[] operations = ["grant-tracked", "remove-global-tracked", "set-tracked", "remove-configuration-tracked", "enable-tracked", "disable-tracked"];
MethodInfo create = type.GetMethod("CreateLifecycleGateway", BindingFlags.Static | BindingFlags.NonPublic)!;
MethodInfo submit = type.GetMethod("SubmitOperation", BindingFlags.Static | BindingFlags.NonPublic)!;
List<object> results = [];
foreach (string operation in operations)
{
    foreach (Exception exception in failures)
    {
        object gateway = create.Invoke(null, [exception])!;
        string? state = null, messageId = null, key = null, thrown = null;
        bool? ambiguous = null;
        try
        {
            Task task = (Task)submit.Invoke(null, [gateway, operation, false])!;
            await task;
            object result = task.GetType().GetProperty("Result")!.GetValue(task)!;
            Type resultType = result.GetType();
            state = resultType.GetProperty("State")!.GetValue(result)?.ToString();
            messageId = resultType.GetProperty("MessageId")!.GetValue(result)?.ToString();
            key = resultType.GetProperty("SafeMessageKey")!.GetValue(result)?.ToString();
            ambiguous = (bool)resultType.GetProperty("IsAmbiguousFailure")!.GetValue(result)!;
        }
        catch (Exception ex)
        {
            Exception cause = ex is TargetInvocationException invocation ? invocation.InnerException! : ex;
            thrown = cause.GetType().Name;
        }
        results.Add(new { operation, input = exception.GetType().Name,
            statusCode = exception.GetType().GetProperty("StatusCode")?.GetValue(exception),
            retryable = exception.GetType().GetProperty("Retryable")?.GetValue(exception),
            state, ambiguous, messageId, key, thrown });
    }
}
Console.WriteLine(JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
